/* Black-Scholes : valeur du call, payoff, delta (tangente) & Greeks */
(function () {
  var svg = document.getElementById("grk-chart");
  if (!svg) return;
  var R = 0.02; // taux sans risque
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }

  function ncdf(x){
    var k=1/(1+0.2316419*Math.abs(x));
    var d=0.3989423*Math.exp(-x*x/2);
    var p=d*k*(0.3193815+k*(-0.3565638+k*(1.781478+k*(-1.821256+k*1.330274))));
    return x>=0 ? 1-p : p;
  }
  function npdf(x){ return 0.3989423*Math.exp(-x*x/2); }

  function bs(S,K,sig,T){
    var sq=sig*Math.sqrt(T);
    var d1=(Math.log(S/K)+(R+sig*sig/2)*T)/sq;
    var d2=d1-sq;
    var price=S*ncdf(d1)-K*Math.exp(-R*T)*ncdf(d2);
    var delta=ncdf(d1);
    var gamma=npdf(d1)/(S*sq);
    var vega=S*npdf(d1)*Math.sqrt(T);           // par 1.00 de vol
    var theta=-(S*npdf(d1)*sig)/(2*Math.sqrt(T)) - R*K*Math.exp(-R*T)*ncdf(d2); // annuel
    var rho=K*T*Math.exp(-R*T)*ncdf(d2);        // par 1.00 de taux
    return {price:price,delta:delta,gamma:gamma,vega:vega,theta:theta,rho:rho};
  }

  function draw(){
    var S=v("grk-s"), K=v("grk-k"), sig=v("grk-v")/100, T=v("grk-t");
    setT("grk-s-o", S.toFixed(0)); setT("grk-k-o", K.toFixed(0));
    setT("grk-v-o", (sig*100).toFixed(0)+"%"); setT("grk-t-o", T.toFixed(1));
    var g0=bs(S,K,sig,T);
    setT("grk-price", g0.price.toFixed(2));
    setT("grk-delta", g0.delta.toFixed(3));
    setT("grk-gamma", g0.gamma.toFixed(4));
    setT("grk-vega", (g0.vega/100).toFixed(3));       // par 1 %
    setT("grk-theta", (g0.theta/365).toFixed(4));     // par jour calendaire
    setT("grk-rho", (g0.rho/100).toFixed(3));         // par 1 %

    var W=520,H=260,L=42,Rm=14,T2=14,B=30, pw=W-L-Rm, ph=H-T2-B;
    var xmin=Math.max(1, K*0.5), xmax=K*1.5;
    var N=90, xs=[], val=[], pay=[];
    for (var i=0;i<=N;i++){ var s=xmin+(xmax-xmin)*i/N; xs.push(s); val.push(bs(s,K,sig,T).price); pay.push(Math.max(s-K,0)); }
    var ymax=0; for (var j=0;j<=N;j++){ ymax=Math.max(ymax,val[j],pay[j]); } ymax*=1.08;
    function px(s){ return L + (s-xmin)/(xmax-xmin)*pw; }
    function py(y){ return T2 + (1-y/ymax)*ph; }

    var g="";
    // axes
    g+='<line class="axis" x1="'+L+'" y1="'+T2+'" x2="'+L+'" y2="'+(T2+ph)+'"/>';
    g+='<line class="axis" x1="'+L+'" y1="'+(T2+ph)+'" x2="'+(L+pw)+'" y2="'+(T2+ph)+'"/>';
    // tangente delta au point courant
    var pDelta0=g0.price;
    function tang(s){ return pDelta0 + g0.delta*(s-S); }
    var t1=tang(xmin), t2=tang(xmax);
    g+='<line x1="'+px(xmin).toFixed(1)+'" y1="'+py(Math.max(0,Math.min(ymax,t1))).toFixed(1)+'" x2="'+px(xmax).toFixed(1)+'" y2="'+py(Math.max(0,Math.min(ymax,t2))).toFixed(1)+'" stroke="var(--gold)" stroke-width="1.8" stroke-dasharray="5 3"/>';
    // payoff (crimson)
    var pp="M "+px(xs[0]).toFixed(1)+","+py(pay[0]).toFixed(1);
    for (var k1=1;k1<=N;k1++) pp+=" L "+px(xs[k1]).toFixed(1)+","+py(pay[k1]).toFixed(1);
    g+='<path d="'+pp+'" fill="none" stroke="var(--crimson)" stroke-width="1.8"/>';
    // valeur BS (teal)
    var vp="M "+px(xs[0]).toFixed(1)+","+py(val[0]).toFixed(1);
    for (var k2=1;k2<=N;k2++) vp+=" L "+px(xs[k2]).toFixed(1)+","+py(val[k2]).toFixed(1);
    g+='<path d="'+vp+'" fill="none" stroke="var(--teal)" stroke-width="2.6"/>';
    // strike marker
    g+='<line x1="'+px(K).toFixed(1)+'" y1="'+T2+'" x2="'+px(K).toFixed(1)+'" y2="'+(T2+ph)+'" stroke="var(--ink-mute)" stroke-width="1" stroke-dasharray="2 3"/>';
    g+='<text class="tick" x="'+px(K).toFixed(1)+'" y="'+(T2+11)+'" text-anchor="middle">K</text>';
    // point courant
    g+='<circle cx="'+px(S).toFixed(1)+'" cy="'+py(g0.price).toFixed(1)+'" r="4" fill="var(--ink)"/>';
    // ticks
    g+='<text class="tick" x="'+L+'" y="'+(H-16)+'" text-anchor="start">'+xmin.toFixed(0)+'</text>';
    g+='<text class="tick" x="'+px(S).toFixed(1)+'" y="'+(H-16)+'" text-anchor="middle">S='+S.toFixed(0)+'</text>';
    g+='<text class="tick" x="'+(L+pw)+'" y="'+(H-16)+'" text-anchor="end">'+xmax.toFixed(0)+'</text>';
    g+='<text class="tick" x="'+(L-6)+'" y="'+(py(ymax)+4).toFixed(1)+'" text-anchor="end">'+ymax.toFixed(0)+'</text>';
    g+='<text class="tick" x="'+(L-6)+'" y="'+(py(0)+0).toFixed(1)+'" text-anchor="end">0</text>';
    var xlab = al()==="en"?"underlying price (S)":(al()==="nl"?"koers onderliggende (S)":"cours du sous-jacent (S)");
    var ylab = al()==="en"?"call value":(al()==="nl"?"callwaarde":"valeur du call");
    g+='<text class="lab" x="'+(L+pw/2)+'" y="'+(H-3)+'" text-anchor="middle">'+xlab+'</text>';
    g+='<text class="lab" x="'+(L-32)+'" y="'+(T2+ph/2)+'" text-anchor="middle" transform="rotate(-90 '+(L-32)+' '+(T2+ph/2)+')">'+ylab+'</text>';
    svg.innerHTML=g;
  }

  ["grk-s","grk-k","grk-v","grk-t"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
